CREATE TABLE `blog_categories` (
  `id` bigint NOT NULL,
  `parent_id` bigint,
  `name` varchar(80) NOT NULL,
  `slug` varchar(100) NOT NULL UNIQUE,
  `depth` integer NOT NULL
);
CREATE TABLE `blog_tags` (
  `id` bigint NOT NULL,
  `name` varchar(60) NOT NULL UNIQUE,
  `slug` varchar(80) NOT NULL UNIQUE
);
CREATE TABLE `customers` (
  `id` bigint NOT NULL,
  `name` varchar(160) NOT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(32),
  `city` varchar(120),
  `postcode` varchar(12),
  `country` char(2) NOT NULL,
  `source` varchar(16) NOT NULL,
  `created_at` datetime NOT NULL
);
CREATE TABLE `dealerships` (
  `id` bigint NOT NULL,
  `name` varchar(160) NOT NULL,
  `code` varchar(12) NOT NULL UNIQUE,
  `address` varchar(200) NOT NULL,
  `city` varchar(120) NOT NULL,
  `region` varchar(120),
  `postcode` varchar(12) NOT NULL,
  `country` char(2) NOT NULL,
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `phone` varchar(32),
  `email` varchar(255),
  `opened_on` date
);
CREATE TABLE `options_catalog` (
  `id` bigint NOT NULL,
  `name` varchar(80) NOT NULL UNIQUE,
  `category` varchar(16) NOT NULL
);
CREATE TABLE `staff` (
  `id` bigint NOT NULL,
  `dealership_id` bigint NOT NULL,
  `name` varchar(160) NOT NULL,
  `email` varchar(255) NOT NULL UNIQUE,
  `phone` varchar(32),
  `role` varchar(20) NOT NULL,
  `hired_on` date NOT NULL,
  `active` boolean NOT NULL
);
CREATE TABLE `blog_posts` (
  `id` bigint NOT NULL,
  `category_id` bigint,
  `author_id` bigint NOT NULL,
  `title` varchar(200) NOT NULL,
  `slug` varchar(220) NOT NULL,
  `excerpt` varchar(400),
  `body` text NOT NULL,
  `status` varchar(12) NOT NULL DEFAULT 'draft',
  `view_count` bigint NOT NULL DEFAULT 0,
  `reading_minutes` integer NOT NULL,
  `published_at` datetime,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
);
CREATE TABLE `blog_comments` (
  `id` bigint NOT NULL,
  `post_id` bigint NOT NULL,
  `parent_id` bigint,
  `author_name` varchar(120) NOT NULL,
  `author_email` varchar(255),
  `body` text NOT NULL,
  `status` varchar(12) NOT NULL,
  `depth` integer NOT NULL,
  `created_at` datetime NOT NULL
);
CREATE TABLE `blog_post_tag` (
  `post_id` bigint NOT NULL,
  `tag_id` bigint NOT NULL
);
CREATE TABLE `cms_pages` (
  `id` bigint NOT NULL,
  `parent_id` bigint,
  `author_id` bigint,
  `title` varchar(200) NOT NULL,
  `slug` varchar(220) NOT NULL,
  `template` varchar(40) NOT NULL,
  `content` text,
  `status` varchar(12) NOT NULL,
  `depth` integer NOT NULL,
  `published_at` datetime,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
);
CREATE TABLE `cms_page_revisions` (
  `id` bigint NOT NULL,
  `page_id` bigint NOT NULL,
  `revision_no` integer NOT NULL,
  `editor_id` bigint,
  `content` text NOT NULL,
  `created_at` datetime NOT NULL
);
CREATE TABLE `media_assets` (
  `id` bigint NOT NULL,
  `uploaded_by` bigint,
  `file_name` varchar(255) NOT NULL,
  `extension` varchar(8) NOT NULL,
  `mime_type` varchar(80) NOT NULL,
  `size_bytes` bigint NOT NULL,
  `checksum` char(64) NOT NULL,
  `width_px` integer,
  `height_px` integer,
  `alt_text` varchar(255),
  `created_at` datetime NOT NULL
);
CREATE TABLE `navigation_menu_items` (
  `id` bigint NOT NULL,
  `parent_id` bigint,
  `page_id` bigint,
  `label` varchar(80) NOT NULL,
  `url` varchar(255),
  `position` integer NOT NULL,
  `depth` integer NOT NULL
);
CREATE TABLE `vehicle_makes` (
  `id` bigint NOT NULL,
  `name` varchar(60) NOT NULL UNIQUE,
  `country` char(2)
);
CREATE TABLE `vehicle_models` (
  `id` bigint NOT NULL,
  `make_id` bigint NOT NULL,
  `name` varchar(80) NOT NULL,
  `body_type` varchar(20) NOT NULL,
  `segment` varchar(20)
);
CREATE TABLE `listings` (
  `id` bigint NOT NULL,
  `dealership_id` bigint NOT NULL,
  `make_id` bigint NOT NULL,
  `model_id` bigint NOT NULL,
  `stock_number` varchar(16) NOT NULL UNIQUE,
  `vin` char(17) NOT NULL UNIQUE,
  `title` varchar(200) NOT NULL,
  `slug` varchar(220) NOT NULL,
  `year` smallint NOT NULL,
  `price` decimal(12,2) NOT NULL,
  `mileage_km` integer NOT NULL,
  `fuel` varchar(12) NOT NULL,
  `transmission` varchar(12) NOT NULL,
  `drivetrain` varchar(8) NOT NULL,
  `color` varchar(24) NOT NULL,
  `condition` varchar(8) NOT NULL,
  `status` varchar(12) NOT NULL,
  `description` text,
  `listed_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `sold_at` datetime
);
CREATE TABLE `customer_favorites` (
  `customer_id` bigint NOT NULL,
  `listing_id` bigint NOT NULL,
  `saved_at` datetime NOT NULL
);
CREATE TABLE `listing_images` (
  `id` bigint NOT NULL,
  `listing_id` bigint NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `extension` varchar(8) NOT NULL,
  `mime_type` varchar(80) NOT NULL,
  `size_bytes` bigint NOT NULL,
  `checksum` char(64) NOT NULL,
  `sort_order` integer NOT NULL,
  `is_primary` boolean NOT NULL
);
CREATE TABLE `listing_options` (
  `listing_id` bigint NOT NULL,
  `option_id` bigint NOT NULL
);
CREATE TABLE `price_history` (
  `id` bigint NOT NULL,
  `listing_id` bigint NOT NULL,
  `price` decimal(12,2) NOT NULL,
  `reason` varchar(24),
  `changed_at` datetime NOT NULL
);
CREATE TABLE `test_drive_requests` (
  `id` bigint NOT NULL,
  `listing_id` bigint NOT NULL,
  `customer_id` bigint NOT NULL,
  `dealership_id` bigint NOT NULL,
  `sales_rep_id` bigint,
  `channel` varchar(12) NOT NULL,
  `requested_at` datetime NOT NULL,
  `preferred_at` datetime,
  `status` varchar(16) NOT NULL,
  `license_verified` boolean NOT NULL,
  `notes` text
);
CREATE TABLE `test_drives` (
  `id` bigint NOT NULL,
  `request_id` bigint NOT NULL,
  `listing_id` bigint NOT NULL,
  `customer_id` bigint NOT NULL,
  `sales_rep_id` bigint NOT NULL,
  `requested_at` datetime NOT NULL,
  `scheduled_at` datetime NOT NULL,
  `started_at` datetime NOT NULL,
  `ended_at` datetime NOT NULL,
  `duration_minutes` integer NOT NULL,
  `distance_km` decimal(8,2) NOT NULL,
  `odometer_start` integer NOT NULL,
  `odometer_end` integer NOT NULL,
  `outcome` varchar(16) NOT NULL,
  `weather` varchar(16)
);
CREATE TABLE `sales` (
  `id` bigint NOT NULL,
  `listing_id` bigint NOT NULL,
  `customer_id` bigint NOT NULL,
  `sales_rep_id` bigint NOT NULL,
  `dealership_id` bigint NOT NULL,
  `test_drive_id` bigint,
  `reference` varchar(20) NOT NULL UNIQUE,
  `currency` char(3) NOT NULL,
  `subtotal` decimal(14,2) NOT NULL,
  `tax_total` decimal(14,2) NOT NULL,
  `grand_total` decimal(14,2) NOT NULL,
  `deposit` decimal(12,2) NOT NULL,
  `payment_method` varchar(16) NOT NULL,
  `financed` boolean NOT NULL,
  `closed_at` datetime NOT NULL
);
CREATE TABLE `activity_log` (
  `id` bigint NOT NULL,
  `causer_id` bigint,
  `subject_type` varchar(24) NOT NULL,
  `subject_id` bigint NOT NULL,
  `event` varchar(24) NOT NULL,
  `properties` json,
  `ip_address` varchar(45),
  `created_at` datetime NOT NULL
);
CREATE TABLE `sale_line_items` (
  `id` bigint NOT NULL,
  `sale_id` bigint NOT NULL,
  `item_type` varchar(16) NOT NULL,
  `description` varchar(200) NOT NULL,
  `quantity` integer NOT NULL,
  `unit_price` decimal(14,2) NOT NULL,
  `tax_amount` decimal(14,2) NOT NULL,
  `line_total` decimal(14,2) NOT NULL
);
CREATE TABLE `test_drive_gps_logs` (
  `id` bigint NOT NULL,
  `test_drive_id` bigint NOT NULL,
  `sequence_no` bigint NOT NULL,
  `recorded_at` datetime NOT NULL,
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `speed_kmh` decimal(6,2) NOT NULL,
  `heading_deg` smallint NOT NULL,
  `altitude_m` decimal(7,2),
  `accuracy_m` decimal(6,2) NOT NULL,
  `satellites` smallint
);
